mod solution;use solution::retry_plan;#[test]fn contract(){assert_eq!(retry_plan("503,429,200,500"),Some("0,1".to_string()));
assert_eq!(retry_plan("200,503"),Some("".to_string()));
assert_eq!(retry_plan("503,404"),Some("fatal@1".to_string()));
assert_eq!(retry_plan("408,504"),Some("0,1".to_string()));
assert_eq!(retry_plan("99"),None);
assert_eq!(retry_plan("600"),None);
assert_eq!(retry_plan("503,,200"),None);
assert_eq!(retry_plan("+503"),None);}
